 private void homeTouch(MotionEvent e){float x=e.getX()*160/Math.max(1,scene.getWidth()),y=e.getY()*192/Math.max(1,scene.getHeight());if(state().sleeping()&&x<67&&y>43&&y<122){roomAction(36,0,3);return;}if(onPet(e)){roomAction(15,0,3);return;}if(x<66&&y>42&&y<120){roomAction(36,0,3);return;}if(x>113&&y>127&&y<158){feedMenu();return;}if(x<44&&y>128&&y<166){roomAction(34,0,4);return;}if(y>171&&state().waste>0){roomAction(3,0,3);return;}if(x>110&&y>20&&y<87){room=5;rebuild();}}
 private android.graphics.drawable.GradientDrawable panel(int color,int stroke,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setStroke(dp(1),stroke);d.setCornerRadius(dp(radius));return d;}
